//! Tranche M (s-22600) C-42b -- contract test for the deterministic
//! `plugins_macros` fuzz corpus generated by
//! `crates/plugins_macros/examples/corpusgen.rs`.
//!
//! Scope (4 cases):
//!   * `contract_corpus_file_meets_min_tuple_floor` -- when the corpus
//!     file is present (regenerable via
//!     `cargo run --example corpusgen -p elai_plugins_macros`), the
//!     line count MUST meet the `MCP_FUZZ_CORPUS_MIN_TUPLES` floor.
//!     The test is SKIP-WHEN-EMPTY (CI green without a corpusgen
//!     prereq) per D-M3 in the Tranche M context package.
//!   * `contract_corpus_tuples_parse_to_canonical_shape` -- every
//!     non-empty line MUST split into the three-column
//!     `(tool_name, authz_decision, expected_emit_count)` tuple shape.
//!   * `contract_corpus_expected_emit_count_matches_dual_emit_rule`
//!     -- per the Tranche D D7 dual-emit decision (see
//!     `workflow/sessions/s-22600/exploration/trancheD-integration.md`),
//!     `Allow` and `Deny` decisions emit 2 SSB rows (gateway authz +
//!     composed verdict); `Ask` emits 1 (HITL pending, gateway only).
//!     The corpus generator hard-codes these mappings; this test pins
//!     them so a future generator refactor cannot silently drift.
//!   * `contract_corpus_min_tuples_const_is_at_least_200` -- pins the
//!     `MCP_FUZZ_CORPUS_MIN_TUPLES` floor at the published value (>=
//!     200) so a future const drop surfaces as a compile-time test
//!     failure rather than a silent corpus-coverage regression.
//!
//! NO test in this file runs the corpus generator -- regeneration is a
//! deliberate human action so the source-of-truth file lives under
//! `crates/plugins_macros/tests/corpus/` and gets reviewed alongside
//! macro-surface changes.

use std::path::PathBuf;

/// Workspace-relative path the corpusgen example writes to. Mirrors
/// the `CORPUS_PATH` const in `examples/corpusgen.rs`; if either side
/// drifts, the file-presence check in test 1 turns into a skip.
const CORPUS_REL_PATH: &str =
    "crates/plugins_macros/tests/corpus/mcp_authz_200_tuples.txt";

/// Repository root, derived from the crate-relative path of this file
/// (`crates/contracts/tests/m_authz_corpus_loop_contract.rs`).
/// Walks up to the workspace root so the corpus path can be resolved
/// from any cwd the test harness picks.
fn workspace_root() -> PathBuf {
    // `env!("CARGO_MANIFEST_DIR")` is `<root>/crates/contracts`; pop
    // twice to reach the workspace root.
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    manifest_dir
        .parent()
        .and_then(|p| p.parent())
        .map(PathBuf::from)
        .unwrap_or(manifest_dir)
}

fn corpus_path() -> PathBuf {
    workspace_root().join(CORPUS_REL_PATH)
}

/// Read every non-empty, non-whitespace-only line in the corpus file.
/// Returns `None` if the file does not exist (skip-when-empty per
/// D-M3); returns `Some(lines)` otherwise.
fn read_corpus_lines() -> Option<Vec<String>> {
    let path = corpus_path();
    if !path.exists() {
        return None;
    }
    let body = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("CONTRACT: corpus file exists but is unreadable: {}", e));
    let lines: Vec<String> = body
        .lines()
        .map(|l| l.trim().to_string())
        .filter(|l| !l.is_empty())
        .collect();
    Some(lines)
}

#[test]
fn contract_corpus_file_meets_min_tuple_floor() {
    let Some(lines) = read_corpus_lines() else {
        eprintln!(
            "SKIP m_authz_corpus_loop_contract::contract_corpus_file_meets_min_tuple_floor \
             -- corpus file absent at `{}`; regenerate via \
             `cargo run --example corpusgen -p elai_plugins_macros`",
            CORPUS_REL_PATH
        );
        return;
    };
    assert!(
        lines.len() >= elai_orchestrator::ssb::MCP_FUZZ_CORPUS_MIN_TUPLES,
        "CONTRACT: corpus tuple count ({}) MUST meet the \
         MCP_FUZZ_CORPUS_MIN_TUPLES floor ({}); regenerate via \
         `cargo run --example corpusgen -p elai_plugins_macros`",
        lines.len(),
        elai_orchestrator::ssb::MCP_FUZZ_CORPUS_MIN_TUPLES
    );
}

#[test]
fn contract_corpus_tuples_parse_to_canonical_shape() {
    let Some(lines) = read_corpus_lines() else {
        eprintln!(
            "SKIP m_authz_corpus_loop_contract::contract_corpus_tuples_parse_to_canonical_shape \
             -- corpus file absent; see prior test for regen command"
        );
        return;
    };
    for (line_no, line) in lines.iter().enumerate() {
        let parts: Vec<&str> = line.split('|').collect();
        assert_eq!(
            parts.len(),
            3,
            "CONTRACT: line {} of corpus does not match \
             `tool_name|authz_decision|expected_emit_count` shape: `{}`",
            line_no + 1,
            line
        );
        let tool_name = parts[0];
        let authz_decision = parts[1];
        let emit_count_raw = parts[2];

        assert!(
            !tool_name.is_empty(),
            "CONTRACT: line {} has empty tool_name", line_no + 1
        );
        assert!(
            matches!(authz_decision, "Allow" | "Deny" | "Ask"),
            "CONTRACT: line {} carries unknown authz_decision `{}`; \
             corpus generator must emit only Allow/Deny/Ask",
            line_no + 1,
            authz_decision
        );
        let _emit: u8 = emit_count_raw.parse().unwrap_or_else(|e| {
            panic!(
                "CONTRACT: line {} emit_count `{}` does not parse as u8: {}",
                line_no + 1,
                emit_count_raw,
                e
            )
        });
    }
}

#[test]
fn contract_corpus_expected_emit_count_matches_dual_emit_rule() {
    let Some(lines) = read_corpus_lines() else {
        eprintln!(
            "SKIP m_authz_corpus_loop_contract::contract_corpus_expected_emit_count_matches_dual_emit_rule \
             -- corpus file absent; see prior test for regen command"
        );
        return;
    };
    for (line_no, line) in lines.iter().enumerate() {
        let parts: Vec<&str> = line.split('|').collect();
        // shape-check already covered by the prior test; bail early if
        // the file is malformed.
        if parts.len() != 3 {
            continue;
        }
        let decision = parts[1];
        let emit_count: u8 = parts[2]
            .parse()
            .unwrap_or_else(|e| panic!("line {} bad emit_count: {}", line_no + 1, e));
        let expected: u8 = match decision {
            // D7 dual-emit: both Allow and Deny fire on the gateway
            // layer AND the composed verdict layer.
            "Allow" => 2,
            "Deny" => 2,
            // Ask is gateway-only until the HITL hand-off resolves.
            "Ask" => 1,
            other => panic!(
                "CONTRACT: line {} unknown decision `{}` (parse test should have caught this)",
                line_no + 1,
                other
            ),
        };
        assert_eq!(
            emit_count, expected,
            "CONTRACT: line {} decision `{}` emit_count={} disagrees with \
             D7 dual-emit rule (expected {}); see \
             workflow/sessions/s-22600/exploration/trancheD-integration.md \
             for the dual-emit specification",
            line_no + 1, decision, emit_count, expected
        );
    }
}

#[test]
fn contract_corpus_min_tuples_const_is_at_least_200() {
    assert!(
        elai_orchestrator::ssb::MCP_FUZZ_CORPUS_MIN_TUPLES >= 200,
        "CONTRACT: MCP_FUZZ_CORPUS_MIN_TUPLES is pinned at >= 200 \
         (5 tools * 5 FSM states * 8 arg shapes baseline per D-M8); \
         a lower value would silently weaken the fuzz corpus coverage \
         floor enforced by `contract_corpus_file_meets_min_tuple_floor`."
    );
}
